<template>
  <!-- Your main content with the icon to trigger the popup -->
  <q-icon
    name="info"
    class="cursor-pointer"
    size="18px"
    :color="hasInputError(fieldName) ? 'red' : ''"
    data-test="info-panel-icon"
    @click.stop="openOrigin"
  />

  <!-- Popup with hoverable content -->
  <q-tooltip
    class="border border-border bg-popover! px-3! py-2! text-sm! text-popover-foreground! shadow-md!"
    @before-hide="removeColorFromFields()"
  >
    <div class="flex max-w-[350px] flex-col gap-1.5">
      <div class="font-semibold">
        {{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}
      </div>
      <div class="text-muted-foreground">{{ $t('checked_automatically') }}</div>
      <div
        v-if="getLowerConfidence(formBuilderModel[fieldName])"
        class="flex items-center gap-1.5 border-t border-border pt-1.5"
      >
        <Icon icon="mdi:check-circle-outline" color="var(--success)" class="size-4" />
        {{ $t('confidence_score') }}:
        <span class="font-semibold">{{ getLowerConfidence(formBuilderModel[fieldName]) }}%</span>
      </div>
      <div
        v-if="hasInputError(fieldName)"
        class="border-t border-border pt-1.5 font-medium text-destructive"
      >
        {{ inputErrorMessage() }}
      </div>
      <div
        v-if="originInteractive"
        data-test="info-panel-origin"
        class="flex items-center gap-1.5 border-t border-border pt-1.5"
      >
        <ExtractionSourceBadge
          :extraction-method="formBuilderModel[fieldName]?.extraction_method"
          :match-source="formBuilderModel[fieldName]?.match_source"
          :lookup-provenance="formBuilderModel[fieldName]?.lookup_provenance"
          :original="formBuilderModel[fieldName]?.original"
          :current-value="String(formBuilderModel[fieldName]?.value ?? '')"
          :interactive="false"
        />
        <span>{{ $t('info_panel_origin_hint') }}</span>
        <Icon icon="mdi:cursor-default-click-outline" color="var(--muted-foreground)" class="size-4" />
      </div>
      <div
        class="flex flex-wrap items-center border-t border-border pt-1.5"
        v-if="hasAnyFormula() && formulaArrayIsFilled()"
      >
        {{
          getFieldLabel(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}
        =
        <template v-for="(step, index) in getCalculationFields()" :key="index">
          <span
            v-if="isInvoiceField(step)"
            data-test="info-panel-field-chip"
            class="m-1 inline-flex items-center gap-1.5 rounded-full border border-(--chip-color)/60 bg-(--chip-color)/20 px-2 py-0.5 text-xs font-medium"
            :style="{ '--chip-color': chipColor(step) }"
            ><span class="size-2 rounded-full bg-(--chip-color)" />{{
              translateLabel('' + getFieldName(step))
            }}</span
          >
          <span class="mx-1" v-else>{{ step }}</span>
        </template>
      </div>
      <div v-if="hasExplanation()" class="border-t border-border pt-1.5 text-xs text-muted-foreground">
        <span class="font-semibold text-foreground">{{ $t('calculation_formula') }}:</span>
        {{ getExplanation() }}
      </div>
    </div>
  </q-tooltip>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { Icon } from '@iconify/vue';
import ExtractionSourceBadge from 'src/components/ExtractionSourceBadge.vue';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { info_panel_chip_colors } from 'src/constants';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';

export default defineComponent({
  name: 'info-panel',
  mixins: [displayFieldLabel, formBuilderHelper],
  components: { Icon, ExtractionSourceBadge },
  props: {
    fieldName: {
      type: String,
      default: '',
    },
    /** true → a click on the icon opens "origin of the value". */
    originInteractive: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['open-origin'],
  methods: {
    openOrigin() {
      if (this.originInteractive) this.$emit('open-origin');
    },
    hasExplanation() {
      const explanationKey = `${this.fieldName}_explanation`;
      const translation = this.$t(explanationKey);
      return translation !== explanationKey;
    },
    getExplanation() {
      return this.$t(`${this.fieldName}_explanation`);
    },
    hasAnyFormula() {
      const hasConfigCalculation =
        !!this.formBuilderConfigModel[this.fieldName].calculation_formula;
      const hasConfigCalculator =
        !!this.formBuilderConfigModel[this.fieldName].calculator_formula;
      const hasModelCalculation =
        !!this.formBuilderModel[this.fieldName].calculation_formula;
      const hasAnyFormula: boolean =
        hasConfigCalculation || hasConfigCalculator || hasModelCalculation;
      return hasAnyFormula;
    },
    chipColor(step: string): string {
      const color = this.fieldColors.get(this.getFieldName(step));
      return color ? `var(--field-link-${color})` : 'var(--primary)';
    },
    isInvoiceField(field_name: string) {
      return field_name.startsWith('[');
    },
    formulaArrayIsFilled() {
      return this.getCalculationFields().length > 0;
    },
    getFormula(): string {
      if (this.formBuilderModel[this.fieldName].calculation_formula) {
         
        return this.formBuilderModel[this.fieldName].calculation_formula;
      }
      if (this.formBuilderConfigModel[this.fieldName].calculation_formula) {
         
        return this.formBuilderConfigModel[this.fieldName].calculation_formula;
      }
      if (this.formBuilderConfigModel[this.fieldName].calculator_formula) {
         
        return this.formBuilderConfigModel[this.fieldName].calculator_formula;
      }
      return '';
    },
    getCalculationFields() {
      let tempStrContainer = '';
      let formulaArray: string[] = [];
      const formula = this.getFormula();
      if (!formula) {
        return formulaArray;
      }
      const tempArray = formula.split(' ');
      for (let index = 0; index < tempArray.length; index = index + 1) {
        tempStrContainer = tempArray[index].trim();
        if (tempArray[index].startsWith('[')) {
          if (tempArray[index] == '[]') {
            continue;
          }
          this.colorField(tempStrContainer);
        }
        formulaArray.push(tempStrContainer);
      }
      return formulaArray;
    },
    inputErrorMessage() {
      let message = '';

      if (!this.formBuilderModel[this.fieldName].input_error) {
        return message;
      }

      const translation_key = this.formBuilderModel[this.fieldName].input_error;
      const translation = this.translateLabel(translation_key);
      message += ' ' + translation + ' ';

      return message;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      fieldColors,
    } = storeToRefs(form_builder_store);
    const {
      isDocumentExtratedField,
      hasInputError,
      removeColorFromFields,
      getFieldName,
      colorField,
    } = form_builder_store;

    return {
      formBuilderModel,
      fieldColors,
      colorField,
      removeColorFromFields,
      getFieldName,
      isFormBuilderMode,
      formBuilderConfigModel,
      isDocumentExtratedField,
      hasInputError,
      info_panel_chip_colors,
      coloredFields: ref([{} as any]),
    };
  },
});
</script>
